  100 * SUM(QT_MAT_BAS_BRANCA) / SUM(QT_MAT_BAS + QT_MAT_BAS_PRETA + QT_MAT_BAS_PARDA + QT_MAT_BAS_AMARELA + QT_MAT_BAS_INDIGENA)
FROM 
